\section{Introduction}

\subsection{The problem}

A \emph{non-homogeneous quadratic Diophantine equation} has the shape
\[
F(x) \;=\; Q(x) + \ell(x) + c \;=\; 0, \qquad x \in \Z^n,
\]
where $Q(x) = x^{\T}Bx$ is a quadratic form and $\ell$ is linear. The standard first move is to
complete the square, which---when the linear part lies in the image of twice the bilinear
form---rewrites $F$ as $Q(x-t) + \text{const}$ for a rational shift $t$. All arithmetic of the
original equation is therefore concentrated in the geometry of the shifted lattice $\Z^n - t$ with
respect to $Q$. The basic obstruction is metric, but it is only one of at least three; the other
two---a $2$-adic congruence and a combinatorial weight function---are what this paper isolates.

\subsection{The invariants}

Throughout, $B \in M_n(\Q)$ is symmetric, $Q(x) = x^{\T}Bx$, $L = \Z^n$, and
$\Bil(x,y) = x^{\T}By$, so that $Q(x) = \Bil(x,x)$ and
\begin{equation}\label{eq:polar}
Q(x+y) = Q(x) + 2\Bil(x,y) + Q(y).
\end{equation}

\begin{definition}[Positive definiteness]
$Q$ is \emph{positive definite over $\Q$} if $Q(x) > 0$ for every $x \in \Q^n \setminus \{0\}$.
\end{definition}

\begin{definition}[Minimal lattice energy]
A rational $\lamone$ is the \emph{minimal lattice energy} of $Q$ if it is attained
($Q(v) = \lamone$ for some $v \in L\setminus\{0\}$) and is a lower bound
($\lamone \le Q(m)$ for all $m \in L\setminus\{0\}$). This is the homogeneous minimum, the
packing invariant.
\end{definition}

\begin{definition}[Spectral gap]
For rational $t$, a rational $\mu$ is the \emph{spectral gap of $Q$ at $t$} if it is attained
($Q(t-m) = \mu$ for some $m \in L$) and is a lower bound ($\mu \le Q(t-m)$ for all $m \in L$).
We write $\mu(t)$.
\end{definition}

Both are stated as attainment-plus-bound rather than as an infimum, so that every theorem below is
an identity rather than a one-sided estimate.

\begin{definition}[Torsion shift]
For $r \ge 2$, a rational point $t$ is an \emph{$r$-torsion shift} if $rt \in L$ and $t \notin L$;
equivalently $t$ is a nonzero $r$-torsion element of $(L \otimes \Q)/L$.
\end{definition}

\begin{definition}[Half point, deep hole, step shift]
For $v \in L$ write $v/2$ for the point with coordinates $v_i/2$. The \emph{deep hole} of $\Z^n$ is
$(\tfrac12,\dots,\tfrac12)$. For $s \subseteq \{1,\dots,n\}$ the \emph{step shift} $\sigma_s$ has
$(\sigma_s)_i = \tfrac12$ for $i \in s$ and $0$ otherwise; every $2$-torsion class of
$(\tfrac12\Z/\Z)^n \cong \F_2^n$ has a unique step-shift representative.
\end{definition}

\begin{definition}[Shifted theta coefficients]
For $c \in \Q$ set $r_t(c) = \#\{m \in L : Q(t-m) = c\}$. The formal series
$\theta_t(q) = \sum_c r_t(c) q^c$ is the \emph{shifted theta series}; its support is the
\emph{value spectrum} of the non-homogeneous form.
\end{definition}

\section{The archimedean theory: torsion gaps}

\subsection{The scaling identity}

\begin{lemma}[Scaling]\label{lem:scaling}
For $c \in \Q$ and $x \in \Q^n$, $Q(cx) = c^2 Q(x)$.
\end{lemma}
\begin{proof}
Immediate from bilinearity of $\Bil$ in each argument.
\end{proof}

\begin{lemma}[Halving identity]\label{lem:halving}
For $v,m \in L$, $Q\!\left(\tfrac v2 - m\right) = \tfrac14 Q(v - 2m)$. More generally, if
$rt = v \in L$ then $Q(t-m) = \tfrac1{r^2}Q(v - rm)$.
\end{lemma}
\begin{proof}
$t - m = \tfrac1r(v - rm)$; apply Lemma~\ref{lem:scaling} with $c = 1/r$.
\end{proof}

\begin{lemma}[Primitivity]\label{lem:prim}
Let $t$ be an $r$-torsion shift with $rt = v \in L$. Then $v - rm \neq 0$ for every $m \in L$.
\end{lemma}
\begin{proof}
If $v = rm$ then $t = m \in L$, contradicting $t \notin L$.
\end{proof}

\begin{remark}
No positivity and no minimality is used. In the special case $t = v/2$ with $v$ shortest one may
argue differently and more informatively: were $v = 2m$ with $m \neq 0$, then
$\lamone = Q(v) = 4Q(m) \ge 4\lamone$, contradicting $\lamone > 0$. Thus \emph{a shortest vector is
primitive modulo $r$ for every $r \ge 2$}---the single fact that drives both the gap theorem and
the even-multiplicity theorem of Section~\ref{sec:mult}.
\end{remark}

\subsection{The gap theorem and its rigidity}

\begin{theorem}[Torsion gap]\label{thm:gap}
Let $\lamone$ be the minimal lattice energy of $Q$ and let $t$ be an $r$-torsion shift, $r \ge 2$.
Then $Q(t-m) \ge \lamone/r^2$ for every $m \in L$, and hence $\mu(t) \ge \lamone/r^2$.
\end{theorem}
\begin{proof}
Write $rt = v \in L$. By Lemma~\ref{lem:halving}, $Q(t-m) = r^{-2}Q(v-rm)$; by
Lemma~\ref{lem:prim} the integer vector $v - rm$ is nonzero; by minimality $Q(v-rm) \ge \lamone$.
\end{proof}

\begin{theorem}[Attainment at half a shortest vector]\label{thm:attain}
If $Q$ is positive definite with minimal lattice energy $\lamone$ and $Q(v) = \lamone$, then
$\mu(v/r) = \lamone/r^2$ for every $r \ge 2$; in particular $\mu(v/2) = \lamone/4$.
\end{theorem}
\begin{proof}
The lower bound is Theorem~\ref{thm:gap}. Attainment is $m = 0$: by Lemma~\ref{lem:scaling},
$Q(v/r) = r^{-2}Q(v) = \lamone/r^2$.
\end{proof}

Theorem~\ref{thm:attain} disposes of the naive guess $\mu \ge \lamone$: for \emph{every} positive
definite rational form in \emph{every} dimension there is a shift at which $\mu$ equals
$\lamone/4$ exactly. The factor $1/4$ is not an artefact of a lossy argument; its origin is the
index scaling of $2L$ inside $L$.

\begin{example}[Sharpness on $\Z^n$]
For $B = I$, $\lamone = 1$, realised by any standard basis vector $e_1$, and
Theorem~\ref{thm:attain} gives $\mu(e_1/2) = 1/4$. No constant larger than $1/4$ can appear in
Theorem~\ref{thm:gap} with $r = 2$.
\end{example}

\begin{lemma}[Translation invariance]\label{lem:transl}
For any $k \in L$, $\mu(t) = \mu(t+k)$; thus $\mu$ is a well-defined function on $(L\otimes\Q)/L$.
\end{lemma}
\begin{proof}
$m \mapsto m + k$ is a bijection of $L$ carrying $Q(t-m)$ to $Q((t+k)-(m+k))$.
\end{proof}

\begin{theorem}[Rigidity]\label{thm:rigid}
Let $Q$ be positive definite with minimal lattice energy $\lamone$ and let $t$ be an $r$-torsion
shift. Then
\[
\mu(t) = \frac{\lamone}{r^2}
\iff
t \equiv \frac{w}{r} \pmod{L} \text{ for some } w \in L \text{ with } Q(w) = \lamone .
\]
\end{theorem}
\begin{proof}
($\Leftarrow$) By Lemma~\ref{lem:transl} we may assume $t = w/r$; apply Theorem~\ref{thm:attain}.
($\Rightarrow$) The definition of $\mu$ includes attainment: there is $m$ with
$Q(t-m) = \lamone/r^2$. Put $w = rt - rm \in L$. By Lemma~\ref{lem:scaling},
$Q(w) = r^2 Q(t-m) = \lamone$, and $t - m = w/r$.
\end{proof}

So the metric invariant $\mu$, restricted to $r$-torsion classes, \emph{detects the shortest
vectors}: the extremal classes are exactly those of $w/r$ for $w$ realising $\lamone$.

\begin{theorem}[Second gap]\label{thm:second}
Let $\lambda_2$ satisfy $Q(m) \ge \lambda_2$ for every $m \in L\setminus\{0\}$ with
$Q(m) \neq \lamone$. If $t$ is an $r$-torsion shift not of the form $w/r \bmod L$ with
$Q(w) = \lamone$, then $\mu(t) \ge \lambda_2/r^2$. Hence the set of spectral gaps at $r$-torsion
shifts contains no value strictly between $\lamone/r^2$ and $\lambda_2/r^2$.
\end{theorem}
\begin{proof}
Fix $m$ and set $w = rt - rm \in L \setminus \{0\}$. If $Q(w) = \lamone$ then $t \equiv w/r$,
excluded. So $Q(w) \ge \lambda_2$ and $Q(t-m) = r^{-2}Q(w) \ge \lambda_2/r^2$.
\end{proof}

\subsection{Basis independence}

\begin{lemma}[Congruence]\label{lem:congr}
For any $U \in M_n(\Q)$ and $x \in \Q^n$, $Q_{U^{\T}BU}(x) = Q_B(Ux)$.
\end{lemma}
\begin{proof}
A fourfold interchange of summation:
$\sum_{k,l}(U^{\T}BU)_{kl}x_kx_l = \sum_{i,j}B_{ij}(\sum_k U_{ik}x_k)(\sum_l U_{jl}x_l)$.
\end{proof}

\begin{theorem}[Invariance]\label{thm:inv}
Let $U,V \in M_n(\Z)$ with $UV = VU = I$. Then $\lamone$ is the minimal lattice energy of $B$ iff
it is that of $U^{\T}BU$, and $\mu_{U^{\T}BU}(t) = \mu_B(Ut)$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:congr} the value sets coincide after the bijection $m \mapsto Um$ of $L$, whose
inverse is $m \mapsto Vm$; both attainment and lower-bound clauses transfer.
\end{proof}

Every quantity in this paper is therefore a $\mathrm{GL}_n(\Z)$-invariant of the pair (lattice,
form), which is precisely what legitimises lattice reduction as a computational tool.

\subsection{Packing and covering}

\begin{theorem}[Packing--covering inequality]\label{thm:packcov}
Suppose $\mu$ is a covering bound: for every $t \in \Q^n$ there is $m \in L$ with
$Q(t-m) \le \mu$. Then $\mu \ge \lamone/4$.
\end{theorem}
\begin{proof}
Take $v$ realising $\lamone$, apply the covering bound to $t = v/2$, and combine with
Theorem~\ref{thm:gap} for $r = 2$.
\end{proof}

\begin{theorem}[Covering radius of $\Z^n$]\label{thm:cov}
For $B = I$ the squared covering radius is exactly $n/4$: the deep hole satisfies
$\mu((\tfrac12,\dots,\tfrac12)) = n/4$, and $\mu(t) \le n/4$ for every $t$.
\end{theorem}
\begin{proof}
Upper bound: round each coordinate, so $|t_i - m_i| \le \tfrac12$ and $\sum (t_i-m_i)^2 \le n/4$.
Lower bound at the deep hole: each coordinate contributes $(\tfrac12 - m_i)^2 \ge \tfrac14$, with
equality at $m_i \in \{0,1\}$.
\end{proof}

\begin{corollary}\label{cor:ratio}
For $\Z^n$ the covering/packing ratio is $n$, unbounded. For the diagonal form
$Q(x) = \sum a_i x_i^2$ with $a_i > 0$ one has $\lamone = \min_i a_i$ and squared covering radius
$\tfrac14\sum_i a_i$, so the ratio $(\sum_i a_i)/(\min_i a_i)$ is unbounded even at fixed $n$.
\end{corollary}

\section{From gaps to Diophantine unsolvability}

\begin{definition}
A linear form is $\ell(x) = \sum_i b_i x_i$; the general non-homogeneous quadratic form is
$F(x) = Q(x) + \ell(x) + c$.
\end{definition}

\begin{theorem}[Completing the square]\label{thm:cts}
Suppose $B$ is symmetric and $s \in \Q^n$ satisfies $2\Bil(s,x) = \ell(x)$ for all $x$. Then
$F(x) = Q(x+s) + (c - Q(s))$ for all $x$.
\end{theorem}
\begin{proof}
By \eqref{eq:polar}, $Q(x+s) = Q(x) + 2\Bil(s,x) + Q(s) = Q(x) + \ell(x) + Q(s)$.
\end{proof}

The hypothesis that $\ell$ lies in the image of $2\Bil$ is exactly the condition for a rational
completing shift to exist; taking it as a hypothesis rather than inverting $B$ keeps the statement
valid for singular $B$. It is non-vacuous: for $B = I$ and $\ell(x) = -\sum_i x_i$ take
$s = -\tfrac12(1,\dots,1)$.

\begin{corollary}[Archimedean criterion]\label{cor:arch}
If $Q$ is positive semidefinite then $F(x) \ge c - Q(s)$ for all real $x$, so $F = 0$ has no
solution when $c > Q(s)$.
\end{corollary}

\begin{theorem}[Lattice-refined criterion]\label{thm:refined}
In the situation of Theorem~\ref{thm:cts}, suppose additionally $-s = v/r$ where $v \in L$ realises
$\lamone$ and $r \ge 2$. Then for every $x \in L$,
\[
F(x) \;\ge\; \frac{\lamone}{r^2} + c - Q(s) \;=\; c ,
\]
since $Q(s) = \lamone/r^2$. Consequently $F(x) = 0$ has no integral solution whenever $c > 0$.
\end{theorem}
\begin{proof}
$Q(x+s) = Q(x - v/r)$ and $v/r$ is an $r$-torsion shift, so Theorem~\ref{thm:gap} gives
$Q(x+s) \ge \lamone/r^2$; now use Theorem~\ref{thm:cts}.
\end{proof}

Comparing Corollary~\ref{cor:arch} with Theorem~\ref{thm:refined}: the classical test rejects
$c > \lamone/r^2$, the lattice test rejects $c > 0$. \textbf{The improvement is exactly
$\lamone/r^2$, the whole of the spectral gap.} The same comparison holds for an arbitrary
completing shift.

\begin{theorem}[General refined criterion]\label{thm:refinedgen}
In the situation of Theorem~\ref{thm:cts}, for every $x \in L$,
\[
F(x) \;\ge\; \mu(-s) + c - Q(s),
\]
so $F(x) = 0$ has no integral solution once $c > Q(s) - \mu(-s)$. The improvement over
Corollary~\ref{cor:arch} is exactly $\mu(-s)$, the spectral gap at the completing shift.
\end{theorem}
\begin{proof}
$Q(x+s) = Q((-s) - (-x)) \ge \mu(-s)$ because $-x \in L$; combine with Theorem~\ref{thm:cts}.
\end{proof}

Theorem~\ref{thm:refined} is the case $-s = v/r$ with $Q(v) = \lamone$, so that
$\mu(-s) = \lamone/r^2 = Q(s)$ and the threshold becomes $c > 0$. Another instance is $B = I$
with $-s$ the deep hole of $\Z^n$, where $Q(s) = \mu(-s) = n/4$ and the threshold is again
$c > 0$; this is the case worked out next.

\begin{corollary}[Unsolvability below the gap]
For any $r$-torsion shift $t$ and any $c < \lamone/r^2$ the equation $Q(x-t) = c$ has no integral
solution. Purely integrally: if $Q(v) = \lamone$ then $Q(w) \ge \lamone$ for every $w \in v + 2L$,
so $Q(w) = N$ has no solution with $w \equiv v \pmod{2L}$ when $N < \lamone$.
\end{corollary}

\begin{proposition}\label{prop:concrete}
For $B = I$ and $\ell(x) = -\sum_i x_i$, so $s = -\tfrac12(1,\dots,1)$, $Q(s) = n/4$ and
$F(x) = \sum_i(x_i^2 - x_i) + c$: for every
$x \in \Z^n$ the integer $\sum_i(x_i^2 - x_i)$ is even and non-negative. Hence
$\sum_i(x_i^2-x_i) + c = 0$ forces $c$ to be a non-positive even integer, and $c = 0$ forces
$x_i \in \{0,1\}$ for all $i$.
\end{proposition}
\begin{proof}
$x_i^2 - x_i = x_i(x_i-1)$ is a product of consecutive integers.
\end{proof}

The archimedean bound alone gives only $\sum_i(x_i^2-x_i) \ge -n/4$---off by the whole gap and
blind to the evenness, which the next section explains structurally.

\section{The \texorpdfstring{$2$}{2}-adic theory: characteristic vectors and the law modulo eight}

\subsection{The deep-hole spectrum of \texorpdfstring{$\Z^n$}{Zn}}

\begin{theorem}[Deep-hole spectrum]\label{thm:deephole}
For $B = I$ and $t = (\tfrac12,\dots,\tfrac12)$, every attained value of $Q(t-m)$, $m \in \Z^n$,
lies in $\tfrac n4 + 2\Z_{\ge 0}$. Hence distinct attained values differ by at least $2$, and both
$n/4$ and $n/4 + 2$ are attained for $n \ge 1$.
\end{theorem}
\begin{proof}
$4Q(t-m) = \sum_i (1-2m_i)^2$ is a sum of $n$ odd squares, and
$(2k-1)^2 = 8\binom k2 + 1 \equiv 1 \pmod 8$ with $\binom k2 \ge 0$. Summing,
$4Q(t-m) = n + 8N$ with $N \ge 0$. Attainment of $n/4$ is $m = 0$; of $n/4+2$, take $m$ with a
single coordinate $-1$, since $3^2 = 1 + 8$.
\end{proof}

\begin{corollary}
The equation $\sum_{i=1}^n (2x_i - 1)^2 = N$ is unsolvable in integers unless $N \equiv n \pmod 8$
and $N \ge n$.
\end{corollary}

Integrality of $4Q$ would give only a gap of $1/4$ in the value spectrum;
Theorem~\ref{thm:deephole} gives $2$, a factor of eight better.

\subsection{Characteristic vectors}

Assume now $B \in M_n(\Z)$ symmetric, so $Q$ and $\Bil$ are integer valued on $L$.

\begin{definition}[Characteristic vector]\label{def:char}
A vector $v \in L$ is \emph{characteristic} for $Q$ if
$\Bil(v,u) + Q(u) \equiv 0 \pmod 2$ for every $u \in L$, i.e. the functional
$u \mapsto \Bil(v,u) + Q(u)$ is everywhere even. (Over $\Z^n$ with the dot product this is the
familiar condition $v \cdot u \equiv u \cdot u \pmod 2$ for all $u$.)
\end{definition}

\begin{lemma}[Fundamental expansion]\label{lem:expand}
For symmetric integral $B$ and $v,u \in L$,
\[
Q(v + 2u) \;=\; Q(v) + 4\bigl(\Bil(v,u) + Q(u)\bigr).
\]
\end{lemma}
\begin{proof}
By \eqref{eq:polar} with $y = 2u$: $Q(v+2u) = Q(v) + 2\Bil(v,2u) + Q(2u)
= Q(v) + 4\Bil(v,u) + 4Q(u)$.
\end{proof}

\begin{theorem}[Characteristic Vector Criterion]\label{thm:char}
Let $B$ be symmetric integral and $v \in L$. Then
\[
v \text{ is characteristic} \iff 8 \mid Q(v+2u) - Q(v) \text{ for every } u \in L .
\]
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:expand}, $Q(v+2u) - Q(v) = 4T_u$ with $T_u = \Bil(v,u) + Q(u)$, and
$8 \mid 4T_u \iff 2 \mid T_u$; both directions follow at once, uniformly in $u$.
\end{proof}

\begin{remark}
The statement is an equivalence, so it cannot be vacuous: the mod-$8$ congruence is not a
coincidence of $\Z^n$ but an exact characterisation of characteristic vectors in every integral
lattice. It is also sharp in the failure direction: if $v$ is not characteristic then some $u$ has
$T_u$ odd, whence $Q(v+2u) \equiv Q(v) + 4 \pmod 8$, breaking the gap from $2$ down to $1$.
Positive definiteness is used nowhere in this subsection.
\end{remark}

\begin{proposition}[The all-ones vector]\label{prop:allones}
For $B = I$ the vector $w = (1,\dots,1)$ is characteristic, since
$\Bil(w,u) + Q(u) = \sum_i u_i + \sum_i u_i^2 = \sum_i u_i(1+u_i)$, a sum of products of
consecutive integers.
\end{proposition}

Applying Theorem~\ref{thm:char} to Proposition~\ref{prop:allones} recovers the arithmetic of
Theorem~\ref{thm:deephole}, and Proposition~\ref{prop:concrete} becomes the statement that $0$ is
characteristic-shifted by $w$.

\subsection{The spectral consequence}

\begin{theorem}[Characteristic shifted spectrum]\label{thm:charspec}
Let $B$ be symmetric integral and $v \in L$ characteristic. Then for every $m \in L$ there is
$k \in \Z$ with
\[
Q\!\left(\tfrac v2 - m\right) \;=\; \frac{Q(v)}{4} + 2k .
\]
That is, the value spectrum at the half of a characteristic vector lies in $\tfrac{Q(v)}4 + 2\Z$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:halving}, $Q(v/2 - m) = \tfrac14 Q(v + 2(-m))$; by Theorem~\ref{thm:char} with
$u = -m$, $Q(v + 2(-m)) = Q(v) + 8k$. Divide by $4$.
\end{proof}

\begin{theorem}[Gap two]\label{thm:gaptwo}
In the situation of Theorem~\ref{thm:charspec}, if $m,m' \in L$ give distinct values then
\[
\left| Q\!\left(\tfrac v2 - m\right) - Q\!\left(\tfrac v2 - m'\right) \right| \;\ge\; 2 .
\]
\end{theorem}
\begin{proof}
Write the values as $\tfrac{Q(v)}4 + 2k$ and $\tfrac{Q(v)}4 + 2k'$ with $k,k' \in \Z$;
distinctness forces $k \neq k'$, hence $|k-k'| \ge 1$ and the difference is $\ge 2$.
\end{proof}

Together, Theorems~\ref{thm:char}, \ref{thm:charspec} and \ref{thm:gaptwo} give the slogan:
\emph{gap $2$ in the shifted value spectrum $\iff$ the shift is half a characteristic vector}. The
deep-hole theorem for $\Z^n$ is the case $v = (1,\dots,1)$.

\begin{remark}[Two independent fours]
The constant $4$ appears both as the denominator in $\lamone/4$ and as the multiplier in
Lemma~\ref{lem:expand}. Both come from the index scaling of $2L$ in $L$, but the two theorems are
logically independent: Theorem~\ref{thm:attain} is archimedean, insensitive to congruences;
Theorem~\ref{thm:char} is $2$-adic, insensitive to the metric and valid without positive
definiteness. Combined, they give the complete local picture at a half characteristic vector
realising $\lamone$: the smallest attained value is $\lamone/4$ and the next possible one is
$\lamone/4 + 2$.
\end{remark}

\section{Multiplicities: parity of shifted theta coefficients}\label{sec:mult}

\begin{theorem}[Even multiplicity]\label{thm:even}
Let $B$ be an arbitrary rational matrix and $t$ a rational shift with $2t = v \in L$ and
$t \notin L$. Then $r_t(c)$ is even for every $c$.
\end{theorem}
\begin{proof}
Let $\iota(m) = v - m$. Since $t = v/2$, $t - \iota(m) = -(t-m)$, and $Q$ is even, so $\iota$
preserves each fibre. It is an involution, and it has no fixed point: $\iota(m) = m$ means
$v = 2m$, i.e. $t = m \in L$, excluded. A fixed-point-free involution of a finite set partitions it
into pairs.
\end{proof}

No minimality, positivity or symmetry hypothesis is needed: the involution only requires
$v \notin 2L$.

\begin{proposition}
If all coefficients $r_t(c)$ are even then $t \notin L$.
\end{proposition}
\begin{proof}
If $t = k \in L$ then $r_t(0) = 1$ for positive definite $Q$, since $Q(k-m) = 0$ forces $m = k$.
\end{proof}

\begin{theorem}[Rank one]\label{thm:rankone}
For $n = 1$ with $Q(x) = x^2$ and $t \in \Q$: all $r_t(c)$ are even $\iff$ $2t \in \Z$ and
$t \notin \Z$.
\end{theorem}
\begin{proof}
($\Leftarrow$) Theorem~\ref{thm:even}. ($\Rightarrow$) Suppose $2t \notin \Z$. If
$(t-m)^2 = (t-m')^2$ with $m \neq m'$ then $m + m' = 2t \in \Z$, a contradiction; so every fibre
has at most one element, and the fibre over $c = t^2$ contains $m = 0$, giving $r_t(t^2) = 1$.
\end{proof}

\begin{theorem}[The naive converse fails in rank two]\label{thm:counter}
Let $n = 2$, $B = I$, $t = (\tfrac12,\tfrac13)$. Then every $r_t(c)$ is even, but
$2t = (1,\tfrac23) \notin \Z^2$.
\end{theorem}
\begin{proof}
The partial reflection $\rho(m_1,m_2) = (1-m_1, m_2)$ is an involution of $\Z^2$; it preserves
$(m_1-\tfrac12)^2 + (m_2-\tfrac13)^2$ because $(1-m_1)-\tfrac12 = -(m_1-\tfrac12)$; and it has no
fixed point because $m_1 = 1-m_1$ has no integer solution.
\end{proof}

Structurally: the standard theta series factors over coordinates, $\theta_t = \prod_i \theta_{t_i}$,
and a single even factor annihilates the product modulo $2$. Evenness is a coordinatewise, not a
global, phenomenon---for forms that split.

\begin{definition}
A rational $x$ is \emph{half-integral} if $x \in \Z + \tfrac12$.
\end{definition}

\begin{theorem}[Parity criterion, diagonal case]\label{thm:parity}
Let $Q(x) = \sum_i a_i x_i^2$ with all $a_i > 0$, and $t \in \Q^n$. Then
\[
\bigl(\forall c,\ r_t(c) \text{ even}\bigr) \iff \bigl(\exists i,\ t_i \text{ half-integral}\bigr).
\]
\end{theorem}
\begin{proof}
($\Leftarrow$) If $t_{i_0} = k + \tfrac12$, the partial flip
$\rho(m)_{i_0} = 2k+1-m_{i_0}$, $\rho(m)_i = m_i$ for $i \neq i_0$, satisfies
$t_{i_0} - \rho(m)_{i_0} = -(t_{i_0}-m_{i_0})$ and leaves the other coordinates alone, hence
preserves $Q(t-\cdot)$ because the diagonal form has no coupling between coordinates. It is an
involution and is fixed-point free since $2m_{i_0} = 2k+1$ is impossible.

($\Rightarrow$) Suppose no coordinate is half-integral. Then
$m^\ast = (\round(t_1),\dots,\round(t_n))$ is the \emph{unique} minimiser of $Q(t-\cdot)$: for each
$i$ one has $|t_i - \round(t_i)| < \tfrac12$ strictly (exactly where non-half-integrality is used)
while $|t_i - k| \ge \tfrac12$ for every integer $k \neq \round(t_i)$; multiplying by $a_i > 0$ and
summing, any $m \neq m^\ast$ has $Q(t-m) > Q(t-m^\ast)$. Hence the bottom coefficient is $1$, odd.
\end{proof}

\begin{corollary}
For $B = I$: all shifted theta coefficients at $t$ are even $\iff$ some coordinate $t_i$ is
half-integral. Theorem~\ref{thm:rankone} is the case $n = 1$, and Theorem~\ref{thm:counter} is the
shift $t = (\tfrac12,\tfrac13)$, whose first coordinate is half-integral.
\end{corollary}

\begin{theorem}[General-rank obstruction]\label{thm:obstruction}
For an arbitrary positive definite $Q$ and shift $t$: if the bottom coefficient of the shifted
theta series is even, then the nearest lattice point to $t$ is not unique.
\end{theorem}
\begin{proof}
The bottom coefficient counts the minimisers of $Q(t-\cdot)$; if unique, the count is $1$, odd.
\end{proof}

What obstructs a rank-$n$ proof of the naive converse is that a coefficient can be even ``by
accident'', two unrelated pairs of lattice points landing at the same distance; the rank-one
argument works only because the fibre of $x \mapsto x^2$ over $c$ has at most two points.

\section{The combinatorial theory: the covering weight enumerator}

\begin{theorem}[Gap at a step shift, standard form]\label{thm:step}
For $B = I$ and any $s \subseteq \{1,\dots,n\}$, $\mu(\sigma_s) = |s|/4$.
\end{theorem}
\begin{proof}
$Q(\sigma_s - m) = \sum_{i \in s}(\tfrac12-m_i)^2 + \sum_{i \notin s} m_i^2 \ge |s|/4$, since each
term of the first sum is a half-integer squared and each of the second is non-negative; both bounds
are attained simultaneously at $m = 0$.
\end{proof}

The key structural point is \emph{additivity}: the standard form splits over coordinates and the
coordinatewise minima are achieved at the same lattice point. This is exactly what fails for a
general form, where off-diagonal entries couple the coordinates.

\begin{theorem}[Gap of a $2$-torsion class $=$ Hamming weight $/\,4$]\label{thm:hamming}
For $B = I$ and $t$ with $2t = v \in \Z^n$,
\[
\mu(t) = \frac k4, \qquad k = \#\{i : v_i \text{ odd}\},
\]
a quarter of the Hamming weight of the class of $t$ in $\F_2^n$.
\end{theorem}
\begin{proof}
Write $t = \sigma_s + \kappa$ with $s = \{i : v_i \text{ odd}\}$ and $\kappa \in \Z^n$; apply
Lemma~\ref{lem:transl} and Theorem~\ref{thm:step}.
\end{proof}

\begin{theorem}[Gap spectrum of $\Z^n$]\label{thm:spectrum}
The set of spectral gaps of $\Z^n$ at $2$-torsion shifts is exactly
$\{\,k/4 : 1 \le k \le n\,\}$.
\end{theorem}
\begin{proof}
($\subseteq$) Theorem~\ref{thm:hamming}, with $k \ge 1$ because $t \notin \Z^n$. ($\supseteq$) For
each $k$ take any $k$-element $s$ and use Theorem~\ref{thm:step}.
\end{proof}

Both endpoints are familiar: $k=1$ is the extremal class of Theorem~\ref{thm:rigid} (gap
$\lamone/4 = 1/4$) and $k = n$ is the deep hole (gap $n/4$, Theorem~\ref{thm:cov}). The metric
invariant $\mu$ on $2$-torsion classes \emph{is} the Hamming weight function of $\F_2^n$, divided
by four.

\begin{theorem}[Weighted weight enumerator, diagonal case]\label{thm:weighted}
Let $Q(x) = \sum_i a_i x_i^2$ with $a_i > 0$. Then:
\begin{enumerate}
\item $\mu(\sigma_s) = \tfrac14\sum_{i \in s} a_i$ for every $s \subseteq \{1,\dots,n\}$;
\item for $t$ with $2t = v \in \Z^n$, $\mu(t) = \tfrac14\sum_{i : v_i \text{ odd}} a_i$;
\item the $2$-torsion gap spectrum is exactly
$\bigl\{\tfrac14\sum_{i\in s}a_i : \emptyset \neq s \subseteq \{1,\dots,n\}\bigr\}$;
\item its minimum is $\tfrac14\min_i a_i = \lamone/4$, the packing invariant, and its maximum is
$\tfrac14\sum_i a_i$, the covering invariant.
\end{enumerate}
\end{theorem}
\begin{proof}
(1) $Q(\sigma_s - m) = \sum_{i \in s}a_i(\tfrac12-m_i)^2 + \sum_{i \notin s}a_i m_i^2 \ge
\tfrac14\sum_{i \in s}a_i$, attained at $m=0$, exactly as in Theorem~\ref{thm:step} with the
positive weights carried along. (2) Translation invariance as in Theorem~\ref{thm:hamming}.
(3) Both inclusions as in Theorem~\ref{thm:spectrum}. (4) The sum over $s$ is minimised at
singletons and maximised at $s = \{1,\dots,n\}$; $\lamone = \min_i a_i$ since a nonzero integer
vector has $\sum a_i m_i^2 \ge \min_i a_i$, attained at a basis vector; and the deep hole realises
the covering radius by the rounding argument of Theorem~\ref{thm:cov}.
\end{proof}

Part (4) is the striking one: a single formula, the weighted Hamming weight, interpolates between
the two classical extremal constants of the geometry of numbers---packing at weight one, covering
at full weight---and takes every intermediate value indexed by a subset.

\section{Algorithms}

\paragraph{Minimal lattice energy by bounded enumeration.}
Enumerate $m \in \{-R,\dots,R\}^n \setminus \{0\}$ and minimise $Q(m)$. Correctness for a given $R$
holds once $R$ exceeds the Cholesky radius: if $Q \succeq \delta\|\cdot\|^2$ then any $m$ with
$\|m\|_\infty > \sqrt{Q(e_1)/\delta}$ has $Q(m) > Q(e_1)$. Cost $O((2R+1)^n n^2)$ exact rational
operations. Reducing the basis first is legitimate by Theorem~\ref{thm:inv} and shrinks $R$
dramatically.

\paragraph{Spectral gap by bounded enumeration over a coset.}
Enumerate $m \in \{-R,\dots,R\}^n$ and minimise $Q(t-m)$. Two accelerations: by
Lemma~\ref{lem:transl} replace $t$ by its representative in $[0,1)^n$, which lets $R$ be small; and
by Theorem~\ref{thm:gap} terminate as soon as the value $\lamone/r^2$ is met when $t$ is an
$r$-torsion shift, since that value is then provably minimal.

\paragraph{Gap spectrum of a diagonal form.}
Theorem~\ref{thm:weighted} turns an exponential lattice search into a subset sum: enumerate the
$2^n-1$ nonempty $s$ and emit $\tfrac14\sum_{i\in s}a_i$. For $a_i \equiv 1$ this collapses to
$\{k/4 : 1 \le k \le n\}$, computable in $O(n)$.

\paragraph{Testing whether a vector is characteristic.}
Definition~\ref{def:char} quantifies over all $u \in L$, but $u \mapsto \Bil(v,u) + Q(u) \bmod 2$
depends only on $u \bmod 2$ and is $\F_2$-linear: since
$Q(u) = \sum_i B_{ii}u_i^2 + 2\sum_{i<j}B_{ij}u_iu_j \equiv \sum_i B_{ii}u_i \pmod 2$, one has
\[
v \text{ characteristic} \iff (Bv)_i \equiv B_{ii} \pmod 2 \text{ for } i = 1,\dots,n,
\]
testable in $O(n^2)$. Characteristic vectors thus form a coset.

\paragraph{Shifted theta coefficients and parity certification.}
Enumerate the shifted lattice within a radius and bucket the exact rational values.
Theorems~\ref{thm:even} and \ref{thm:parity} provide \emph{certificates}: instead of counting,
exhibit the fixed-point-free involution (the full reflection $m \mapsto 2t-m$, or the partial flip
in a half-integral coordinate) and verify in $O(n)$ that it preserves the form and has no fixed
point---turning an unbounded verification into a constant-size proof.

\section{Applications}

\textbf{Solvability testing.} Theorem~\ref{thm:refined} gives an implementable test strictly
dominating the classical complete-the-square criterion whenever the completing shift is a torsion
point of a shortest vector, improving the rejected range by exactly $\lamone/r^2$;
Theorem~\ref{thm:deephole} adds an orthogonal congruential filter.

\textbf{Covering-radius estimation.} Theorem~\ref{thm:packcov} bounds the covering radius from a
shortest-vector computation alone; Theorem~\ref{thm:weighted}(4) shows that for diagonal forms the
bound and the truth differ by $(\sum a_i)/(\min a_i)$, quantifying exactly how lossy packing-based
covering estimates are.

\textbf{Coding-theoretic dictionary.} Theorem~\ref{thm:weighted} identifies the geometric function
``distance from a $2$-torsion class to the lattice'' with the weighted Hamming weight on $\F_2^n$,
so questions about the distribution of $\mu$ over $2$-torsion classes become questions about
weight enumerators of binary codes, and conversely.

\textbf{Structure of value spectra.} Theorem~\ref{thm:gaptwo} says representable values skip by at
least $2$ at the half of a characteristic vector---a factor-of-eight strengthening over
integrality---and, being a complete criterion, failure of the gap is itself informative.

\textbf{Basis-independent invariants.} Theorem~\ref{thm:inv} licenses lattice reduction as
preprocessing for every quantity above, which is what makes the enumerations feasible beyond toy
dimensions.

\section{Discussion}

Three separate mechanisms lie behind the single question ``when does $Q(x) = c$ have no integral
solution near a given shift?''.

The \emph{archimedean mechanism} is a scaling argument: an $r$-torsion shift is $1/r$ of an
integral vector, and $1/r$ of a nonzero integral vector has energy at least $\lamone/r^2$. Its
content is not the inequality, which is three lines, but the rigidity: the equality case pins down
the shortest vectors exactly, and there is a further gap above the extremal classes. Notably the
hypotheses shrink as the theory develops---the inequality needs only $t \notin L$---and the naive
guess $\mu \ge \lamone$ is off by precisely the index-scaling factor $4$.

The \emph{$2$-adic mechanism} is the expansion $Q(v+2u) = Q(v) + 4(\Bil(v,u)+Q(u))$ together with
$8 \mid 4T \iff 2 \mid T$. This converts a mod-$8$ statement into a mod-$2$ statement about a
linear functional, hence into the classical notion of a characteristic vector, and the mod-$8$ law
of sums of odd squares stops being a curiosity of $\Z^n$.

The \emph{combinatorial mechanism} is additivity of a diagonal form over coordinates, with
coordinatewise minima attained simultaneously. This is genuinely restrictive: for a general form
the off-diagonal entries couple the coordinates and the minimum is not additive. The theorem is
sharp in its hypothesis rather than in its proof.

The multiplicity theory offers a cautionary tale. The rank-one criterion is exact and very tempting
to promote to all ranks; the promotion is false, because $t = (\tfrac12,\tfrac13)$ in $\Z^2$ has
all coefficients even thanks to the first coordinate alone. The failure is instructive: parity of
the theta series is a factorisation phenomenon, and it points to the correct statement
(Theorem~\ref{thm:parity}), which is stronger, cleaner, and covers the whole diagonal family.

\section{Future directions}

\textbf{A reflection criterion for parity in arbitrary rank.} Theorem~\ref{thm:parity} is proved
for diagonal forms, where a single-coordinate reflection is available. The right general statement
should replace ``some $t_i$ is half-integral'' by ``there is an isometry $\rho$ of $(L,Q)$ with
$\rho^2 = \mathrm{id}$ and $\rho(t) \equiv t \pmod L$ acting freely on $L$'';
Theorem~\ref{thm:obstruction} is the first step.

\textbf{The van der Blij invariant.} For an even unimodular lattice, $Q(v) \equiv \sgn(Q) \pmod 8$
for every characteristic $v$. Theorem~\ref{thm:char} gives the local version---$Q(v) \bmod 8$ is
constant on $v + 2L$---from which the global statement should be reachable by a genus argument.

\textbf{Strictness of the packing--covering inequality.} Theorem~\ref{thm:packcov} gives
covering $\ge \lamone/4$ and Corollary~\ref{cor:ratio} shows the ratio is unbounded for diagonal
forms; determining for which lattices equality holds remains open.

\textbf{The weight enumerator of a general lattice.} Define $W_L : L/2L \to \Q$ by
$W_L(\bar t) = \mu(t/2)$. Theorem~\ref{thm:weighted} computes $W_L$ for diagonal forms as a
weighted Hamming weight; for a general form $W_L$ is a new invariant whose symmetry group,
extremal values, and rigidity are all open.

\textbf{A Eureka threshold.} For which $N$ does $\sum_i(2x_i-1)^2 = N$ acquire many solutions, and
how does the multiplicity grow? Theorem~\ref{thm:deephole} fixes the support; the density of
solutions on that progression is not addressed here.

\textbf{Higher torsion spectra.} Theorem~\ref{thm:spectrum} computes the $2$-torsion gap spectrum
of $\Z^n$ completely. For $r \ge 3$ the spectrum is not a Hamming weight and its combinatorial
description should be a weight enumerator over $\Z/r$ rather than $\F_2$.

\section{Summary of results}

\begin{center}
\begin{longtable}{p{0.28\textwidth}p{0.64\textwidth}}
\toprule
\textbf{Result} & \textbf{Statement} \\
