"""
Exact Torsion Gap Certification by Coset Reduction
==================================================

Computes the spectral gap  mu(t) = min_{m in L} Q(t - m)  of a positive definite
rational quadratic form Q(x) = x^T B x on L = Z^n at a rational shift t, and
certifies extremality against the torsion bound lambda_1 / r^2.

The two accelerations are theorems, not heuristics:

  * translation invariance:  mu(t) = mu(t + k) for every k in L, so t may first
    be reduced into the fundamental domain [0,1)^n;
  * the torsion bound: if r t lies in L and t does not, then mu(t) >= lambda_1/r^2,
    so the search may terminate the instant that value is met.

Complexity: O((2R+1)^n * n^2) exact rational operations for a box of radius R,
with R = 1 sufficing after coset reduction for well-conditioned B (in general R
must exceed the Cholesky radius sqrt(Q(e_1)/delta) where Q >= delta * ||.||^2).
"""

from __future__ import annotations

from fractions import Fraction
from itertools import product
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

Rat = Fraction
Mat = Sequence[Sequence[Rat]]


def quad(B: Mat, x: Sequence[Rat]) -> Rat:
    """Q(x) = x^T B x, evaluated exactly."""
    total = Fraction(0)
    for i, row in enumerate(B):
        for j, bij in enumerate(row):
            if bij:
                total += bij * x[i] * x[j]
    return total


def box(n: int, radius: int) -> Iterable[Tuple[int, ...]]:
    """All integer vectors in {-radius, ..., radius}^n."""
    return product(range(-radius, radius + 1), repeat=n)


def minimal_lattice_energy(B: Mat, radius: int = 3) -> Rat:
    """lambda_1 = min { Q(m) : m in Z^n \\ {0} }, by bounded enumeration."""
    n = len(B)
    best: Optional[Rat] = None
    for m in box(n, radius):
        if not any(m):
            continue
        value = quad(B, tuple(Fraction(c) for c in m))
        if best is None or value < best:
            best = value
    assert best is not None
    return best


def coset_reduce(t: Sequence[Rat]) -> Tuple[Rat, ...]:
    """Replace t by its representative in [0,1)^n; mu is unchanged."""
    return tuple(c - (c.numerator // c.denominator) for c in t)


def torsion_order(t: Sequence[Rat]) -> Optional[int]:
    """The exact order r of t in (L tensor Q)/L, or None if t lies in L."""
    order = 1
    for c in t:
        order = order * c.denominator // _gcd(order, c.denominator)
    return None if order == 1 else order


def _gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a


def spectral_gap_certified(
    B: Mat, t: Sequence[Rat], radius: int = 3
) -> Dict[str, object]:
    """
    Return the spectral gap at t together with a certificate of extremality.

    Keys of the result:
      'mu'            the exact spectral gap min_m Q(t - m);
      'minimisers'    every lattice point attaining it inside the search box;
      'lambda_1'      the minimal lattice energy of Q;
      'order'         the torsion order r of t, or None if t is in the lattice;
      'torsion_bound' lambda_1 / r^2 when r is defined;
      'extremal'      True exactly when mu equals the torsion bound, which by
                      the rigidity theorem happens iff t = w/r mod L for some w
                      realising lambda_1;
      'witness'       such a w, when the shift is extremal.
    """
    n = len(B)
    lam = minimal_lattice_energy(B, radius)
    reduced = coset_reduce(t)
    order = torsion_order(reduced)
    bound = None if order is None else lam / (order * order)

    best: Optional[Rat] = None
    minimisers: List[Tuple[int, ...]] = []
    for m in box(n, radius):
        value = quad(B, tuple(reduced[i] - m[i] for i in range(n)))
        if best is None or value < best:
            best, minimisers = value, [m]
        elif value == best:
            minimisers.append(m)
        if bound is not None and best == bound:
            break                      # provably minimal: stop early

    assert best is not None
    extremal = bound is not None and best == bound
    witness: Optional[Tuple[int, ...]] = None
    if extremal and order is not None:
        m0 = minimisers[0]
        witness = tuple(int(order * (reduced[i] - m0[i])) for i in range(n))

    return {
        "mu": best,
        "minimisers": minimisers,
        "lambda_1": lam,
        "order": order,
        "torsion_bound": bound,
        "extremal": extremal,
        "witness": witness,
    }


if __name__ == "__main__":
    B = [[Fraction(1), Fraction(0)], [Fraction(0), Fraction(5)]]   # x^2 + 5y^2
    for shift in ([Fraction(1, 2), Fraction(0)],
                  [Fraction(0), Fraction(1, 2)],
                  [Fraction(1, 3), Fraction(1, 3)]):
        report = spectral_gap_certified(B, shift)
        print(shift, "->", {k: str(v) for k, v in report.items()})
